      "filename": "payment_service/app/routes/payments.py",
      "language": "python",
      "description": "Implements all core payment endpoints including create, get, refund, retry, and list.",
      "code": "from fastapi import APIRouter, HTTPException, Request, Query
from typing import Optional
from uuid import uuid4
from app.schemas.payment_schema import PaymentCreate, PaymentResponse, PaymentListResponse, RefundRequest, RefundResponse, PaymentRetryResponse
from app.services import redis_service, kafka_service, stripe_service
from app.models.payment_model import PaymentModel
from app.models.refund_model import RefundModel
from app.logging.audit import log_action

router = APIRouter()

@router.post('/', response_model=PaymentResponse)
async def create_payment(request: Request, payload: PaymentCreate):
    if await redis_service.is_duplicate(payload.idempotency_key):
        existing = await PaymentModel.get_by_idempotency_key(payload.idempotency_key)
        if existing:
            return existing.to_response()
    payment = await PaymentModel.create(amount=payload.amount, currency=payload.currency, method=payload.method, customer_id=payload.customer_id, idempotency_key=payload.idempotency_key, metadata=payload.metadata)
    await redis_service.store_idempotency_key(payload.idempotency_key, payment.id)
    await kafka_service.publish_event('payments.events', {'event': 'payment_created', 'payment_id': str(payment.id)})
    log_action('payment_created', payment_id=str(payment.id), amount=payment.amount)
    return payment.to_response()

@router.get('/{id}', response_model=PaymentResponse)
async def get_payment(id: str):
    payment = await PaymentModel.get_by_id(id)
    if not payment:
        raise HTTPException(status_code=404, detail={"type": "https://example.com/not-found", "title": "Payment Not Found", "status": 404, "detail": "No payment found for given ID"})
    return payment.to_response()

@router.get('/', response_model=PaymentListResponse)
async def list_payments(status: Optional[str] = Query(None), date_from: Optional[str] = Query(None), date_to: Optional[str] = Query(None), page: int = 1, page_size: int = 20):
    payments, total = await PaymentModel.list_filtered(status, date_from, date_to, page, page_size)
    return {'page': page, 'page_size': page_size, 'total_count': total, 'payments': [p.to_response() for p in payments]}

@router.post('/{id}/refund', response_model=RefundResponse)
async def refund_payment(id: str, request: Request, payload: RefundRequest):
    payment = await PaymentModel.get_by_id(id)
    if not payment or payment.status != 'completed':
        raise HTTPException(status_code=400, detail={"type": "https://example.com/invalid-status", "title": "Invalid Payment Status", "status": 400, "detail": "Only completed payments can be refunded."})
    if payload.refund_amount > payment.amount:
        raise HTTPException(status_code=400, detail={"type": "https://example.com/invalid-amount", "title": "Refund amount exceeds payment", "status": 400, "detail": "Refund amount cannot exceed the original payment."})
    refund = await RefundModel.create(payment_id=id, refund_amount=payload.refund_amount, reason=payload.reason, metadata=payload.metadata)
    await kafka_service.publish_event('payments.events', {'event': 'refund_initiated', 'refund_id': str(refund.id), 'payment_id': id})
    log_action('refund_initiated', payment_id=id, refund_id=str(refund.id), amount=refund.refund_amount)
    return refund.to_response()

@router.post('/{id}/retry', response_model=PaymentRetryResponse)
async def retry_payment(id: str):
    payment = await PaymentModel.get_by_id(id)
    if not payment or payment.status != 'failed':
        raise HTTPException(status_code=400, detail={"type": "https://example.com/invalid-operation", "title": "Cannot retry payment", "status": 400, "detail": "Only failed payments can be retried."})
    await kafka_service.publish_event('payments.events', {'event': 'payment_retry', 'payment_id': id})
    log_action('payment_retry', payment_id=id)
    return {'payment_id': id, 'retry_attempt': payment.retry_attempt + 1 if hasattr(payment, 'retry_attempt') else 1, 'status': 'processing', 'event_id': str(uuid4())}"
